// ELEMENTS:
// 1. Fundo navy liso
// 2. Foto/vídeo (src) emoldurado como numa galeria, com zoom-out lento dentro da moldura
// 3. Filete azul IAD fino à volta da foto, a desenhar-se
// 4. Eyebrow (eyebrow) branco + legenda em serifa branca (anim.text) por baixo
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#161617";
const CYAN = "#FFFFFF";
const CORAL = "#FFFFFF";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const MolduraGaleria: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };
  const zoom = interpolate(f, [0, T], [1.14, 1.0], { ...clamp, easing: Easing.out(Easing.sin) });
  const line = show(0.2, 1.0);
  const inset = 18 * u;

  const photo = (
    <div style={{ position: "relative", flex: land ? "0 0 58%" : undefined, height: land ? "100%" : H * 0.56, opacity: show(0, 0.6) }}>
      <div
        style={{
          position: "absolute",
          inset: -inset,
          border: `${2 * u}px solid ${CYAN}`,
          clipPath: `inset(0 ${(1 - line) * 100}% 0 0)`,
        }}
      />
      <div style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)", transform: `scale(${zoom})` }} />
        ) : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          boxSizing: "border-box",
          padding: land ? `${96 * u}px ${96 * u}px` : `${230 * u}px ${110 * u}px ${150 * u}px`,
          display: "flex",
          flexDirection: land ? "row" : "column",
          alignItems: land ? "center" : "stretch",
          gap: (land ? 96 : 88) * u,
        }}
      >
        {photo}
        <div style={{ display: "flex", flexDirection: "column", gap: 24 * u }}>
          {eyebrow ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.6) }}>
              {eyebrow}
            </div>
          ) : null}
          {caption ? (
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 96 * u, lineHeight: 1.04, color: WHITE, ...rise(0.75) }}>
              {caption}
            </div>
          ) : null}
        </div>
      </div>
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default MolduraGaleria;
